BEGIN;
SET LOCAL app.tenant_id = 'globex';   -- ends with the transaction, never left on a pooled connection
SET LOCAL statement_timeout = '2s';   -- from the plan: caps what one query can cost
SELECT id, name FROM projects;        -- policy: tenant_id = current_setting('app.tenant_id', true)
COMMIT;

INSERT INTO jobs (tenant_id, idempotency_key, kind, status)
VALUES ('globex', '9b77d0', 'bulk_archive', 'queued')
ON CONFLICT (tenant_id, idempotency_key) DO NOTHING RETURNING id;

BEGIN;
SET LOCAL app.tenant_id = 'globex';
SET LOCAL statement_timeout = '2s';
UPDATE projects SET archived = true
WHERE id IN (SELECT id FROM projects
  WHERE updated_at < '2024-01-01' AND NOT archived LIMIT 1000);
